		for (; d < levels; ++d) {
			path[d] = {l, r};
			int digit = (x >> (2 * (levels - 1 - d))) & 3;
			int a = bits[d].rank(l, digit), b = bits[d].rank(r, digit);
			if (a == b) break;
			l = middle[d][digit] + a;
			r = middle[d][digit] + b;
		}
