		for (int i = 0; i < r - l; ++i) a[i] = original[l + i];
		auto swap = [&](int i, int j) {
			auto lo = std::min(a[i], a[j]), hi = std::max(a[i], a[j]);
			a[i] = lo;
			a[j] = hi;
		};
