			int digit = (x >> (3 * (levels - 1 - d))) & 7;
			int a = bits[d].rank(l, digit), b = bits[d].rank(r, digit);
			if (a == b) break;
			l = middle[d][digit] + a;
			r = middle[d][digit] + b;
		}
		if (d == levels) return values[x];
		for (; d >= 0; --d) {
			l = path[d].first;
			r = path[d].second;
