			for (digit += Previous ? -1 : 1; 0 <= digit && digit < 8; digit += Previous ? -1 : 1) {
				int a = bits[d].rank(l, digit), b = bits[d].rank(r, digit);
				if (a == b) continue;
				x = ((x >> shift) & ~std::uint32_t(7)) | digit;
