	}
#endif
	template <bool Previous>
	std::optional<T> neighbor(int l, int r, std::uint32_t x) const {
#if defined(__x86_64__) || defined(__i386__)
		if (vectorized) return neighbor_avx2<Previous>(l, r, x);
#endif
